import test from 'node:test';
import assert from 'node:assert/strict';
import { calculateAdx14, buildChartTrendStrength } from '../src/trend-strength-adx.mjs';

// Independently computed with exact BigInt rational normalized-average recurrence.
// The frozen values are not generated by the implementation under test.
const closes = [100,102,101,105,104,107,106,110,108,109,112,111,115,113,110,108,
  109,107,105,106,104,103,106,109,108,112,115,114,111,109,112,116,118,117,120,119,
  116,113,111,114,118,121,120,124,122,125,123,127];
const prices = closes.map((close, i) => ({ open: close, high: close + i % 3 + 2,
  low: close - (i * 2) % 3 - 1, close }));
const golden = [
  [27,37.36099004367287,31.330941577986714,7.67414790510437,null],
  [28,37.19736283182245,28.779788347579455,13.834772693055966,-0.16362721185041806],
  [35,40.84370495940664,30.729335144226226,8.906951927913989,1.0932979083711187],
  [40,36.77225868343954,28.602570248900268,14.34040792503523,-0.2738767263442505],
  [47,38.577454380744854,31.46397052219137,13.809170372004086,0.032210450620793],
];
const near = (a, b) => assert.ok(Number.isFinite(a) && Math.abs(a - b) < 1e-10, `${a} != ${b}`);
const iso = ms => new Date(ms).toISOString();
const start = Date.parse('2026-11-04T08:45:00+08:00');
const identity = { actualContract: 'TXFK6', tradeDate: '2026-11-04', session: 'DAY', sessionId: '2026-11-04-DAY' };
function fixture(n = 40, timeframe = '5m') {
  const width = { '1m':60000, '5m':300000, '15m':900000, '30m':1800000, '1h':3600000, '4h':14400000 }[timeframe];
  const observed = start + n * width;
  const chart = { schemaVersion: 'governed-tx-decision-chart-v2', barContract: { schemaVersion: 'chart-bar-contract-v2' },
    source: 'SHIOAJI_ACTUAL_TX_EXECUTED_TICK', ...identity, timeframe, mode: 'LIVE',
    asOf: iso(observed + 2000), availableAt: iso(observed + 1000), lastEventTime: iso(observed),
    status: 'READY', qualityStatus: 'PASS', qualityReasons: [], sourceComplete: true,
    contractConsistencyState: 'MATCH', contractRollover: { detected: false },
    sequenceGapEventCount: 0, sequenceGapSize: 0, futureDataViolations: 0,
    structureEligibility: { state: 'ELIGIBLE', reasonCodes: [], audit: { feedCompleteness: 'UNKNOWN_NO_NATIVE_SEQUENCE', captureIntervals: [] } },
    formalWeight: 0, researchOnly: true, executionAuthorized: false, orderRoutesEnabled: false,
    bars: Array.from({ length: n }, (_, i) => ({ ...prices[i % prices.length], ...identity,
      sessionStart: iso(start), sessionEnd: '2026-11-04T05:45:00.000Z',
      time: iso(start + i * width), firstEventTime: iso(start + i * width + 1000),
      lastEventTime: iso(start + (i + 1) * width - 1000), availableAt: iso(start + (i + 1) * width - 500),
      qualityStatus: 'PASS', sequenceGapCount: 0, eventCount: 4, volume: 20,
      structureEligibility: { state: 'ELIGIBLE', reasonCodes: [],
        completionSourceEventTime: iso(start + (i + 1) * width), completionAvailableAt: iso(start + (i + 1) * width + 1000) } })) };
  return chart;
}

test('ADX14 matches independent mixed-path golden values, DI and delta at seed and later positions', () => {
  for (const [index, value, plus, minus, delta] of golden) {
    const r = calculateAdx14(prices.slice(0, index + 1));
    assert.equal(r.state, 'READY'); near(r.value, value); near(r.plusDI, plus); near(r.minusDI, minus);
    if (delta == null) assert.equal(r.deltaADX, null); else near(r.deltaADX, delta);
    assert.equal(r.firstOutputIndex, 27);
  }
});

test('27 bars have no ADX; bar 28 provides the first value, not a fabricated earlier seed', () => {
  for (const n of [0,1,13,14,26,27]) {
    const r = calculateAdx14(prices.slice(0,n)); assert.equal(r.state, 'WARMING_UP'); assert.equal(r.value, null);
  }
  assert.equal(calculateAdx14(prices.slice(0,28)).deltaADX, null);
  assert.notEqual(calculateAdx14(prices.slice(0,29)).deltaADX, null);
});

test('up/down reflection preserves ADX and exchanges DI without converting strength into direction', () => {
  const down = prices.map(b => ({ high: 300 - b.low, low: 300 - b.high, close: 300 - b.close }));
  const a = calculateAdx14(prices), b = calculateAdx14(down);
  near(a.value,b.value); near(a.plusDI,b.minusDI); near(a.minusDI,b.plusDI); near(a.deltaADX,b.deltaADX);
  assert.equal(a.direction,'PLUS_DI_DOMINANT'); assert.equal(b.direction,'MINUS_DI_DOMINANT');
});

test('positive price scaling, translation and changes to irrelevant opens preserve ADX', () => {
  const a = calculateAdx14(prices);
  for (const altered of [prices.map(b=>({high:b.high*5,low:b.low*5,close:b.close*5})),
    prices.map(b=>({high:b.high+1000,low:b.low+1000,close:b.close+1000})), prices.map(b=>({...b,open:b.low}))]) {
    const b=calculateAdx14(altered); near(a.value,b.value); near(a.plusDI,b.plusDI); near(a.minusDI,b.minusDI);
  }
});

test('observed flat and equal-direction movement produce legitimate zero, not missing-data zero', () => {
  const flat = calculateAdx14(Array.from({length:40},()=>({high:100,low:100,close:100})));
  assert.equal(flat.value,0); assert.equal(flat.plusDI,0); assert.equal(flat.minusDI,0); assert.equal(flat.deltaADX,0);
  assert.equal(flat.direction,'EQUAL_DI');
  const tied = calculateAdx14(Array.from({length:40},(_,i)=>({high:150+i,low:100-i,close:125})));
  assert.equal(tied.value,0); assert.equal(tied.direction,'EQUAL_DI');
});

test('numeric missing, coercible, malformed, overflow and over-budget inputs never become values', () => {
  for (const value of [null,undefined,'', '100',false,NaN,Infinity,-1]) {
    const bars=structuredClone(prices); bars[2].high=value;
    assert.equal(calculateAdx14(bars).value,null,String(value));
  }
  const invalid=structuredClone(prices); invalid[3].close=invalid[3].high+1;
  assert.equal(calculateAdx14(invalid).state,'UNAVAILABLE');
  assert.equal(calculateAdx14(Array(10001).fill(prices[0])).reasonCodes[0],'ADX_INPUT_LIMIT_EXCEEDED');
  assert.equal(calculateAdx14(Array(40).fill({high:1e308,low:1,close:1e308})).state,'UNAVAILABLE');
});

test('chart adapter preserves source/identity/as-of and does not mutate its input', () => {
  const chart=fixture(),before=JSON.stringify(chart),r=buildChartTrendStrength(chart);
  assert.equal(r.state,'READY'); near(r.value,calculateAdx14(chart.bars).value);
  assert.equal(r.asOf,chart.asOf); assert.equal(r.sourceAvailableAt,chart.availableAt);
  assert.equal(r.firstUsedBarAt,chart.bars[0].time); assert.equal(r.lastClosedBarAt,iso(start+40*300000));
  assert.equal(r.closedBarCount,40); assert.equal(r.requiredClosedBars,28);
  assert.equal(r.identity.actualContract,'TXFK6'); assert.equal(r.seedMethod,'TA_LIB_WILDER_14_UNSTABLE_0');
  assert.ok(r.limitations.includes('FEED_COMPLETENESS_NOT_CERTIFIED'));
  assert.equal(r.formalWeight,0); assert.equal(r.researchOnly,true);
  assert.equal(r.executionAuthorized,false); assert.equal(r.orderRoutesEnabled,false);
  assert.equal(JSON.stringify(chart),before);
});

test('forming and future bars do not change the closed-bar indicator or enter its sample count', () => {
  const chart=fixture(40), expected=buildChartTrendStrength(chart);
  const open={...chart.bars.at(-1),time:iso(start+40*300000),firstEventTime:iso(start+40*300000),
    lastEventTime:chart.lastEventTime,availableAt:chart.availableAt,
    high:9999,low:1,open:9000,close:9000,structureEligibility:{state:'BLOCKED',reasonCodes:['SOURCE_COMPLETION_NOT_OBSERVED']}};
  chart.bars.push(open,{...open,time:iso(start+41*300000),high:NaN,availableAt:iso(start+42*300000)});
  const actual=buildChartTrendStrength(chart); near(actual.value,expected.value); assert.equal(actual.closedBarCount,40);
});

test('clock cutoff alone cannot close a bar without an observed source event at or after its end', () => {
  const chart=fixture(28); chart.lastEventTime=iso(start+28*300000-1);
  const r=buildChartTrendStrength(chart); assert.equal(r.state,'WARMING_UP'); assert.equal(r.closedBarCount,27); assert.equal(r.value,null);
});

test('replay uses only chart.asOf and is labeled replay, never wall-clock or live evidence', () => {
  const chart=fixture(); chart.mode='REPLAY';
  chart.structureEligibility={state:'BLOCKED',reasonCodes:['LIVE_CURRENT_ONLY']};
  for(const bar of chart.bars) delete bar.structureEligibility;
  const r=buildChartTrendStrength(chart); assert.equal(r.mode,'REPLAY'); assert.equal(r.asOf,chart.asOf);
  assert.equal(r.state,'QUALITY_INSUFFICIENT'); assert.ok(Number.isFinite(r.value));
  assert.ok(r.reasonCodes.includes('CLOSED_BAR_CAPTURE_EVIDENCE_UNVERIFIED'));
});

test('wrong chart/bar identity, order, malformed OHLC and future source watermarks fail closed', () => {
  for(const mutate of [c=>c.bars[4].actualContract='TXFL6',c=>c.bars[4].session='NIGHT',
    c=>c.bars[4].tradeDate='2026-11-03',c=>c.bars[4].time=c.bars[3].time,
    c=>c.bars[4].low=null,c=>c.bars[4].close=c.bars[4].high+1,
    c=>c.availableAt=iso(Date.parse(c.asOf)+1),c=>c.lastEventTime=iso(Date.parse(c.asOf)+1),
    c=>c.executionAuthorized=true,c=>c.contractConsistencyState='MISMATCH']) {
    const chart=fixture(); mutate(chart); const r=buildChartTrendStrength(chart);
    assert.equal(r.state,'UNAVAILABLE'); assert.equal(r.value,null);
  }
});

test('bar availability later than the chart watermark is a contradiction, not a calculable observation', () => {
  const chart=fixture(); chart.bars[4].availableAt=iso(Date.parse(chart.availableAt)+1);
  const r=buildChartTrendStrength(chart); assert.equal(r.state,'UNAVAILABLE'); assert.equal(r.value,null);
  assert.ok(r.reasonCodes.includes('BAR_SOURCE_WATERMARK_CONFLICT'));
});

test('a bar event ahead of the chart source watermark is rejected even when it would look forming', () => {
  const chart=fixture(); chart.lastEventTime=chart.bars.at(-1).lastEventTime.slice(0,19)+'.000Z';
  chart.bars.at(-1).lastEventTime=iso(Date.parse(chart.lastEventTime)+1);
  const r=buildChartTrendStrength(chart); assert.equal(r.state,'UNAVAILABLE'); assert.equal(r.value,null);
  assert.ok(r.reasonCodes.includes('BAR_SOURCE_WATERMARK_CONFLICT'));
});

test('timeframe lookup rejects inherited object keys as unsupported', () => {
  for(const timeframe of ['constructor','toString','__proto__']) {
    const chart=fixture(); chart.timeframe=timeframe;
    const r=buildChartTrendStrength(chart); assert.equal(r.state,'UNAVAILABLE');
    assert.ok(r.reasonCodes.includes('CHART_MODE_OR_TIMEFRAME_UNSUPPORTED'));
  }
});

test('a missing bar restarts the latest contiguous warmup instead of joining across a gap', () => {
  const chart=fixture(40); chart.bars.splice(25,1);
  const r=buildChartTrendStrength(chart); assert.equal(r.state,'WARMING_UP'); assert.equal(r.closedBarCount,14);
  assert.ok(r.reasonCodes.includes('INSUFFICIENT_CLOSED_BARS'));
  assert.ok(r.limitations.includes('RESET_AFTER_BAR_GAP'));
});

test('known capture loss excludes affected bars and restarts the segment, while unrelated old loss can age out', () => {
  const chart=fixture(40); chart.bars[30].captureCoverage={state:'KNOWN_INTERRUPTION'};
  let r=buildChartTrendStrength(chart); assert.equal(r.state,'WARMING_UP'); assert.equal(r.closedBarCount,9);
  assert.ok(r.limitations.includes('RESET_AFTER_CAPTURE_INTERRUPTION'));
  delete chart.bars[30].captureCoverage; chart.bars[3].captureCoverage={state:'KNOWN_INTERRUPTION'};
  r=buildChartTrendStrength(chart); assert.equal(r.closedBarCount,36); assert.equal(r.state,'READY');
  near(r.value,calculateAdx14(chart.bars.slice(4)).value);
});

test('explicit continuity epoch changes never share a smoothing seed', () => {
  const chart=fixture(40); chart.bars.forEach((bar,i)=>{bar.continuityEpoch=i<31?'TX:1':'TX:2';});
  const r=buildChartTrendStrength(chart); assert.equal(r.closedBarCount,9); assert.equal(r.value,null);
  assert.ok(r.limitations.includes('RESET_AFTER_CONTINUITY_EPOCH_CHANGE'));
});

test('source catchup or quality restrictions retain only clearly limited numerical observations', () => {
  for(const mutate of [c=>c.sourceComplete=false,c=>c.qualityStatus='QUALITY_INSUFFICIENT',
    c=>c.bars[12].qualityStatus='QUALITY_INSUFFICIENT',c=>delete c.sourceComplete]) {
    const chart=fixture(); mutate(chart); const r=buildChartTrendStrength(chart);
    assert.equal(r.state,'QUALITY_INSUFFICIENT'); assert.ok(Number.isFinite(r.value)); assert.ok(r.reasonCodes.length);
  }
});

test('source quality reason codes survive as bounded codes alongside the numerical limitation', () => {
  const chart=fixture(); chart.qualityStatus='QUALITY_INSUFFICIENT';
  chart.qualityReasons=['TIMESTAMP_LINEAGE_INSUFFICIENT','x'.repeat(200),'not a reason'];
  chart.bars[10].structureEligibility={state:'BLOCKED',reasonCodes:['SOURCE_EVENT_TIME_REGRESSION']};
  const r=buildChartTrendStrength(chart);
  assert.equal(r.state,'QUALITY_INSUFFICIENT'); assert.ok(Number.isFinite(r.value));
  assert.ok(r.reasonCodes.includes('TIMESTAMP_LINEAGE_INSUFFICIENT'));
  assert.ok(r.reasonCodes.includes('SOURCE_EVENT_TIME_REGRESSION'));
  assert.ok(r.reasonCodes.every(code=>/^[A-Z0-9_]{1,120}$/.test(code))); assert.ok(r.reasonCodes.length<=32);
});

test('an unavailable or stale source status cannot yield a READY derived indicator from retained bars', () => {
  for(const status of ['UNAVAILABLE','STALE','UNKNOWN',null,undefined]) {
    const chart=fixture(); chart.status=status; const r=buildChartTrendStrength(chart);
    assert.equal(r.state,'UNAVAILABLE'); assert.equal(r.value,null);
    assert.ok(r.reasonCodes.includes('CHART_STATUS_UNAVAILABLE'));
  }
});

test('non-five-minute source lacks existing capture proof: descriptive value is limited, never falsely complete', () => {
  const chart=fixture(40,'1m'); chart.structureEligibility={state:'BLOCKED',reasonCodes:['FIVE_MINUTE_STRUCTURE_ONLY']};
  for(const bar of chart.bars) delete bar.structureEligibility;
  const r=buildChartTrendStrength(chart); assert.equal(r.state,'QUALITY_INSUFFICIENT'); assert.ok(Number.isFinite(r.value));
  assert.ok(r.reasonCodes.includes('CLOSED_BAR_CAPTURE_EVIDENCE_UNVERIFIED'));
});

test('invalid, absent and one-bar daily inputs expose absence or insufficient scope without zero-filling', () => {
  assert.equal(buildChartTrendStrength(null).value,null);
  const chart=fixture(1); chart.timeframe='1D'; chart.session='NIGHT_PLUS_DAY'; chart.sessionId='2026-11-04-TRADE_DATE';
  Object.assign(chart.bars[0],{session:chart.session,sessionId:chart.sessionId,time:'2026-11-03T16:00:00.000Z',
    sessionStart:'2026-11-03T07:00:00.000Z',sessionEnd:'2026-11-04T05:45:00.000Z',
    firstEventTime:'2026-11-03T07:00:01.000Z',lastEventTime:'2026-11-04T05:45:00.000Z',availableAt:'2026-11-04T05:45:01.000Z',windowState:'CLOSED'});
  chart.lastEventTime='2026-11-04T05:45:00.000Z';chart.availableAt='2026-11-04T05:45:01.000Z';chart.asOf='2026-11-04T05:45:02.000Z';
  delete chart.bars[0].structureEligibility;
  const r=buildChartTrendStrength(chart);assert.equal(r.state,'UNAVAILABLE');assert.equal(r.closedBarCount,1);assert.equal(r.value,null);
  assert.equal(r.maxSessionClosedBars,1);assert.ok(r.reasonCodes.includes('SESSION_CAPACITY_BELOW_REQUIRED_BARS'));
});

test('single-session capacity distinguishes impossible waiting from attainable DAY/NIGHT warmup', () => {
  for(const [frame,n,capacity] of [['15m',20,20],['30m',10,10],['1h',5,5],['4h',1,1]]) {
    const r=buildChartTrendStrength(fixture(n,frame));
    assert.equal(r.state,'UNAVAILABLE',frame);assert.equal(r.maxSessionClosedBars,capacity);
    assert.ok(r.reasonCodes.includes('SESSION_CAPACITY_BELOW_REQUIRED_BARS'));
  }
  for(const [frame,n,width,capacity] of [['15m',28,900000,56],['30m',28,1800000,28]]) {
    const chart=fixture(n,frame),nightStart=Date.parse('2026-11-03T15:00:00+08:00');
    chart.session='NIGHT';chart.sessionId='2026-11-03-NIGHT';
    chart.lastEventTime=iso(nightStart+n*width);chart.availableAt=iso(nightStart+n*width+1000);chart.asOf=iso(nightStart+n*width+2000);
    chart.bars.forEach((bar,i)=>Object.assign(bar,{session:chart.session,sessionId:chart.sessionId,
      sessionStart:iso(nightStart),sessionEnd:iso(nightStart+14*3600000),time:iso(nightStart+i*width),
      firstEventTime:iso(nightStart+i*width+1000),lastEventTime:iso(nightStart+(i+1)*width-1000),availableAt:iso(nightStart+(i+1)*width-500),
      structureEligibility:{state:'ELIGIBLE',reasonCodes:[],completionSourceEventTime:iso(nightStart+(i+1)*width),completionAvailableAt:iso(nightStart+(i+1)*width+1000)}}));
    const r=buildChartTrendStrength(chart);assert.equal(r.maxSessionClosedBars,capacity);assert.ok(Number.isFinite(r.value));
  }
  const missing=fixture();delete missing.bars[0].sessionEnd;
  const r=buildChartTrendStrength(missing);assert.equal(r.state,'UNAVAILABLE');assert.equal(r.maxSessionClosedBars,null);
  assert.ok(r.reasonCodes.includes('SESSION_CAPACITY_UNVERIFIED'));
});
